package com.hbm.client.radar;
import com.hbm.client.model.*;import com.hbm.machine.radar.RadarBlockEntity;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.AABB;import org.joml.Matrix4f;
/** Original noSmooth HFR radar Base/Dish or large Radar/Dish, rotating only dish with exact world/item offset. */
public final class RadarRenderer implements BlockEntityRenderer<RadarBlockEntity>{public RadarRenderer(BlockEntityRendererProvider.Context c){}static WavefrontMesh mesh(boolean large){return LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),ResourceLocation.parse("hbm:models/machines/radar"+(large?"_large":"")+".obj"));}static void part(boolean large,String texture,PoseStack p,MultiBufferSource buffers,int light,int overlay,String part){LegacyObjRenderer.renderOnly(mesh(large),p,buffers.getBuffer(RenderType.entityCutoutNoCull(ResourceLocation.parse("hbm:textures/models/machines/"+texture+".png"))),light,overlay,-1,LegacyObjRenderer.Convention.HFR_FLAT,part);}@Override public void render(RadarBlockEntity radar,float partial,PoseStack p,MultiBufferSource buffers,int light,int overlay){LegacyContactShadows.render(radar,mesh(radar.large),new Matrix4f().translation(.5F,0,.5F).rotateY((float)Math.PI),p,buffers);p.pushPose();p.translate(.5,0,.5);p.mulPose(Axis.YP.rotationDegrees(180));part(radar.large,radar.large?"radar_large":"radar_base",p,buffers,light,overlay,radar.large?"Radar":"Base");p.mulPose(Axis.YN.rotationDegrees(radar.prevRotation+(radar.rotation-radar.prevRotation)*partial));if(!radar.large)p.translate(-.125,0,0);part(radar.large,radar.large?"radar_large":"radar_dish",p,buffers,light,overlay,"Dish");p.popPose();}@Override public boolean shouldRenderOffScreen(RadarBlockEntity radar){return true;}@Override public int getViewDistance(){return 256;}@Override public AABB getRenderBoundingBox(RadarBlockEntity radar){var p=radar.getBlockPos();return radar.large?new AABB(p.getX()-5,p.getY(),p.getZ()-5,p.getX()+6,p.getY()+10,p.getZ()+6):new AABB(p.getX()-1,p.getY(),p.getZ()-1,p.getX()+2,p.getY()+3,p.getZ()+2);}}
